(function () {
  var p = (pol && pol.data) ? pol.data : {};
  var policyId = String((trg && trg.policy_id) || '');
  if (!policyId) { throw new Error('renewal-generate: the timer payload carries no policy_id'); }
  var expiringQuoteId = String(p.quote_id || (trg && trg.quote_id) || '');
  return {
    policy_id: policyId,
    policy_number: String(p.policy_number || ''),
    expiring_quote_id: expiringQuoteId,
    broker_id: String(p.broker_id || ''),
    // `folder` is queryable through the index filter even though it is not an
    // index_fields entry — verified live on this account. It is the only
    // foreign-key-shaped handle these records have, and it is what makes a
    // regeneration findable without a new schema field.
    existing_renewal_filter: JSON.stringify({ conditions: [
      { field: 'folder', keyword: policyId },
      { field: 'origin', keyword: 'publisher-renewal' }] }),
    original_submission_filter: JSON.stringify({ conditions: [
      { field: 'quote_id', keyword: expiringQuoteId || '__no_quote__' }] }),
    broker_filter: JSON.stringify({ conditions: [
      { field: 'broker_id', keyword: String(p.broker_id || '') || '__no_broker__' }] }),
    now: new Date().toISOString().replace(/\.\d{3}Z$/, 'Z')
  };
})();

(function () {
  function iso(d) { return d.toISOString().replace(/\.\d{3}Z$/, 'Z'); }
  function dedupe(resp) {
    var rows = (resp && resp.data && resp.data.results) ? resp.data.results : [];
    var seen = {}, out = [];
    for (var i = 0; i < rows.length; i++) {
      var r = rows[i];
      if (!r || !r.id || seen[r.id]) continue;
      seen[r.id] = 1; out.push(r);
    }
    return out;
  }
  // ---- answer keys are copied by PATTERN ---------------------------------
  // The question sections are gen_ / clm_ / itcl01_ / ahcl* / cpl_ / gp01_, and
  // every one of those keys exists on BOTH submission_config and quote_config.
  // Copying by pattern rather than by an enumerated list means a question added
  // to the product later is carried across with no flow change, and nothing
  // outside the answer space can leak into either record.
  function isAnswerKey(k) {
    return k.indexOf('gen_') === 0 || k.indexOf('clm_') === 0 || k.indexOf('itcl01_') === 0
        || k.indexOf('ahcl') === 0 || k.indexOf('cpl_') === 0 || k.indexOf('gp01_') === 0;
  }

  var p = (pol && pol.data) ? pol.data : {};
  var existing = dedupe(prior);
  var originals = dedupe(orig);

  // The expiring term's answers: the highest submission version on the
  // expiring quote. version is the submission's own ordering key.
  var src = null;
  for (var i = 0; i < originals.length; i++) {
    if (!src) { src = originals[i]; continue; }
    if (Number((originals[i].data || {}).version || 0) > Number((src.data || {}).version || 0)) src = originals[i];
  }
  var sd = src ? (src.data || {}) : {};

  var regenerate = !!(trg && trg.regenerate);
  var reasons = [];
  if (String(p.policy_status || '') !== 'ACTIVE') reasons.push('policy_status_is_' + (String(p.policy_status || '') || 'absent'));
  if (String(p.auto_renewal_eligible || '') !== 'true') reasons.push('auto_renewal_eligible_is_' + (String(p.auto_renewal_eligible || '') || 'absent'));
  if (!src) reasons.push('no_expiring_submission_to_clone');
  // Idempotency: a renewal already exists for this policy and no regeneration
  // was asked for. 1.3 part 3 — regeneration MINTS A NEW RECORD and supersedes
  // the old through its outcome; it never overwrites one.
  if (existing.length > 0 && !regenerate) reasons.push('renewal_already_generated_' + existing.length);

  // 4.4's Q-REN-{EXPIRING_POLICY_NO} uniqueness defect, closed by construction:
  // the revision suffix is what supersession gives a meaning to (1.3 part 3).
  var revision = existing.length + 1;
  var base = 'Q-REN-' + String(p.policy_number || 'UNKNOWN');
  var quoteReference = (revision <= 1) ? base : (base + '-R' + revision);

  var answers = {};
  for (var k in sd) {
    if (!Object.prototype.hasOwnProperty.call(sd, k)) continue;
    if (isAnswerKey(k)) answers[k] = sd[k];
  }
  var selected = sd.selected_products || [];
  var selections = sd.product_selections || [];
  var primary = (selected && selected.length) ? String(selected[0]) : String(p.product_code || '');
  // 5.3's open question, decided: the renewal is re-evaluated against the
  // CURRENT tables and the CURRENT product version, and a question added to the
  // product since the original bind is simply unanswered — which wave 4's A-11
  // already routes to REFER, never to a silent ACCEPT. The expiring term's
  // version is carried on the quote as a note so the divergence stays visible.
  var productVersion = String(currentProductVersion || sd.product_version || '');

  var brows = (brk && brk.data && brk.data.results) ? brk.data.results : [];
  var to = '', toName = '';
  for (var b = 0; b < brows.length; b++) {
    var bd = brows[b].data || {};
    if (bd.primary_contact_email) { to = String(bd.primary_contact_email); toName = String(bd.brokerage_name || bd.primary_contact_name || ''); break; }
  }
  if (!to) { to = String(fallback || ''); toName = 'Antipodean Operations'; }

  var nowIso = iso(new Date());
  // ---- the 1.3 HANDOVER --------------------------------------------------
  // A quote is minted broker-side by the broker. A publisher-initiated renewal
  // is the one exception, and it is a ONE-TIME act of creation, never an
  // ongoing write: after this record exists the answers are the broker's and
  // this flow never touches it again.
  var brokerQuote = {};
  for (var a in answers) { if (Object.prototype.hasOwnProperty.call(answers, a)) brokerQuote[a] = answers[a]; }
  brokerQuote.selected_products = selected;
  brokerQuote.product_selections = selections;
  brokerQuote.quote_reference = quoteReference;
  brokerQuote.primary_product_code = primary;
  brokerQuote.broker_stage = 'new';
  brokerQuote.pipeline_stage = 'started';
  brokerQuote.inception_date = String(p.expiration_date || '');
  brokerQuote.submitted_at = '';
  brokerQuote.submitted_version = 0;
  brokerQuote.broker_notes = 'Renewal of policy ' + String(p.policy_number || '')
    + ', expiring ' + String(p.expiration_date || '') + '. Pre-filled by the publisher at T-100 '
    + '(handover, plan 1.3): these answers were cloned from the expiring term and are NOT attested '
    + 'by the broker until they are reviewed and resubmitted. Expiring product version '
    + String(sd.product_version || 'unknown') + '; re-evaluated against ' + productVersion + '.';

  return {
    should_generate: reasons.length === 0,
    skip_reasons: reasons,
    regenerate: regenerate,
    revision: revision,
    policy_id: String((trg && trg.policy_id) || ''),
    policy_number: String(p.policy_number || ''),
    expiration_date: String(p.expiration_date || ''),
    expiring_quote_id: String(p.quote_id || ''),
    expiring_submission_id: src ? String(src.id) : '',
    expiring_product_version: String(sd.product_version || ''),
    product_version: productVersion,
    quote_reference: quoteReference,
    primary_product_code: primary,
    policyholder_name: String(sd.gen_policyholder_name || ''),
    existing_renewals: existing.length,
    notice_to: to,
    notice_to_name: toName,
    generated_at: nowIso,
    broker_quote_record: brokerQuote,
    // quote_id on the submission is the DISTRIBUTOR-SIDE QUOTE RECORD ID, so it
    // cannot be known until the handover record exists. STAMP_SUBMISSION injects it.
    submission_stub: (function () {
      var s = {};
      for (var a2 in answers) { if (Object.prototype.hasOwnProperty.call(answers, a2)) s[a2] = answers[a2]; }
      s.selected_products = selected;
      s.product_selections = selections;
      s.product_code_list = (selected || []).join(' ');
      s.product_version = productVersion;
      s.distributor_account_id = String(sd.distributor_account_id || p.broker_id || '');
      s.quote_reference = quoteReference;
      s.version = 1;
      s.received_at = nowIso;
      s.submitted_by = 'system-renewal-generate';
      // 1.3: "these are the answers the broker attested" is not true of a clone.
      s.origin = 'publisher-renewal';
      return s;
    })()
  };
})();

(function () {
  // The submission's quote_id is the broker-side quote RECORD ID — the join key
  // on both sides. It is injected here because the handover record has to exist
  // before the submission that points at it can be written.
  var q = (quote && quote.data && quote.data.id) ? String(quote.data.id) : '';
  if (!q) { throw new Error('renewal-generate: the handover quote returned no record id; refusing to write a submission with no join key'); }
  var out = {};
  for (var k in stub) { if (Object.prototype.hasOwnProperty.call(stub, k)) out[k] = stub[k]; }
  out.quote_id = q;
  return { submission_record: out, quote_id: q };
})();
